import assert from 'node:assert/strict';
import { test } from 'vitest';
import { createGame, activateCard, advanceGame } from '../game.ts';
import { createTournament, TournamentPhase } from './rules.ts';
import { encodeTournament, readTournament, TOURNAMENT_MAX_BYTES } from './format.ts';
import { completedTournament, FOUR_NAMES, FOUR_CODES } from './tournament.fixture.ts';

test('setup, live progress and completed brackets round trip with precise time', () => {
  const tournament = { ...createTournament(FOUR_NAMES, FOUR_CODES), phase: TournamentPhase.playing };
  let game = createGame(FOUR_CODES[0] ?? '');
  game = advanceGame(activateCard(game, 0), 0.25);
  const live = readTournament(encodeTournament(tournament, game));
  assert.deepEqual(live.archive, { tournament, game });
  assert.deepEqual(readTournament(encodeTournament(null, null)).archive, { tournament: null, game: null });
  const done = completedTournament();
  assert.deepEqual(readTournament(encodeTournament(done.tournament, done.game)).archive, done);
});

test('new JSON sorts every object key and names its format', () => {
  const done = completedTournament();
  const text = encodeTournament(done.tournament, done.game);
  const keys: string[][] = [];
  JSON.parse(text, (key, value: unknown) => {
    if (value !== null && typeof value === 'object' && !Array.isArray(value)) keys.push(Object.keys(value));
    return key === '' ? value : value;
  });
  for (const group of keys) assert.deepEqual(group, [...group].sort());
  assert.match(text, /"format": "neon-pairs\/tournament"/);
});

test('imports reject unknown nested fields, impossible scores, altered winners and skipped turns', () => {
  const done = completedTournament();
  const value = JSON.parse(encodeTournament(done.tournament, done.game));
  const change = (edit: (draft: typeof value) => void) => {
    const draft = structuredClone(value); edit(draft); return readTournament(JSON.stringify(draft));
  };
  assert.equal(change((draft) => { draft.tournament.matches[0].results[0].extra = 1; }).error, 'Unknown field: extra.');
  assert.equal(change((draft) => { draft.game.selection.extra = 1; }).error, 'Unknown field: extra.');
  for (const edit of [
    (draft: typeof value) => { draft.tournament.matches[0].winner = 3; },
    (draft: typeof value) => { draft.tournament.matches[0].results[0].moves = 1; },
    (draft: typeof value) => { draft.tournament.matches[0].results[0] = null; },
    (draft: typeof value) => { draft.tournament.matches[1].boardCode = draft.tournament.matches[0].boardCode; },
    (draft: typeof value) => { draft.tournament.players[0] = ' Ada '; },
    (draft: typeof value) => { draft.version = 99; },
  ]) assert.equal(change(edit).archive, null);
  for (const text of ['{', 'null', '[]', '{}', ' '.repeat(TOURNAMENT_MAX_BYTES + 1)])
    assert.equal(readTournament(text).archive, null);
});

